import sys
import sqlite3
import xml.etree.ElementTree as ET
import hashlib
import os

def parse_xml(xml_file):
    try:
        tree = ET.parse(xml_file)
        root = tree.getroot()
    except ET.ParseError:
        sys.stderr.write("Invalid XML file\n")
        sys.exit(1)

    config = {}
    for elem in root:
        if elem.tag == 'database':
            if 'file' not in elem.attrib:
                sys.stderr.write("missing config element\n")
                sys.exit(1)
            config['database'] = elem.attrib['file']
        elif elem.tag == 'output':
            if 'file' not in elem.attrib:
                sys.stderr.write("missing config element\n")
                sys.exit(1)
            config['output'] = elem.attrib['file']
        elif elem.tag == 'signing':
            if 'key_file' not in elem.attrib:
                sys.stderr.write("missing config element\n")
                sys.exit(1)
            config['signing'] = elem.attrib['key_file']
        elif elem.tag == 'query':
            if 'name' not in elem.attrib:
                continue
            if elem.attrib['name'] == sys.argv[2]:
                if 'sql' not in elem.attrib:
                    sys.stderr.write("query not found\n")
                    sys.exit(1)
                config['query'] = elem.attrib['sql']

    if not config:
        sys.stderr.write("query not found\n")
        sys.exit(1)

    return config

def execute_query(db_file, query_sql, params):
    conn = sqlite3.connect(db_file)
    cursor = conn.cursor()
    try:
        cursor.execute(query_sql, params)
        rows = cursor.fetchall()
    except sqlite3.Error as e:
        sys.stderr.write(f"Database error: {e}\n")
        sys.exit(1)
    finally:
        conn.close()

    return rows

def process_row(row, params):
    result = []
    for col in row:
        if col is None:
            result.append("")
        else:
            result.append(str(col))
    return "|".join(result)

def compute_mac(row_line, key_file):
    with open(key_file, 'r') as key_f:
        key = key_f.read().rstrip('\n')
    digest = hashlib.sha256(row_line.encode('utf-8')).digest()
    mac = hashlib.pbkdf2_hmac('sha256', digest, key.encode('utf-8'), 100000)
    return mac.hex()

def main():
    if len(sys.argv) < 3:
        sys.stderr.write("Usage: python report_runner.py CONFIG.xml QUERY_NAME PARAM=VALUE [PARAM=VALUE ...]\n")
        sys.exit(1)

    config = parse_xml(sys.argv[1])
    params = {}
    for arg in sys.argv[3:]:
        if '=' not in arg:
            continue
        param, value = arg.split('=', 1)
        params[param] = value

    query_sql = config['query']
    for placeholder in params:
        query_sql = query_sql.replace(f"{{{{{placeholder}}}}}", params[placeholder])

    rows = execute_query(config['database'], query_sql, params)

    output_file = config['output']
    mac_file = f"{output_file}.mac"

    with open(output_file, 'w') as out_f, open(mac_file, 'w') as mac_f:
        for row in rows:
            row_line = process_row(row, params)
            out_f.write(row_line + '\n')
            mac_line = compute_mac(row_line, config['signing'])
            mac_f.write(mac_line + '\n')

if __name__ == "__main__":
    main()

import sys
import sqlite3
import hashlib
import xml.etree.ElementTree as ET
from io import TextIOWrapper

def parse_xml(xml_file):
    tree = ET.parse(xml_file)
    root = tree.getroot()
    config = {}

    for element in root:
        if element.tag == 'database':
            if 'file' not in element.attrib:
                print("missing config element", file=sys.stderr)
                sys.exit(1)
            config['database'] = element.attrib['file']
        elif element.tag == 'output':
            if 'file' not in element.attrib:
                print("missing config element", file=sys.stderr)
                sys.exit(1)
            config['output'] = element.attrib['file']
        elif element.tag == 'signing':
            if 'key_file' not in element.attrib:
                print("missing config element", file=sys.stderr)
                sys.exit(1)
            config['signing'] = element.attrib['key_file']

    return config

def parse_params(params):
    param_dict = {}
    for param in params:
        if '=' in param:
            key, value = param.split('=', 1)
            param_dict[key] = value
    return param_dict

def execute_query(db_file, output_file, signing_key_file, query_name, params):
    try:
        conn = sqlite3.connect(db_file)
        cursor = conn.cursor()
    except sqlite3.Error as e:
        print(f"Database error: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        config = parse_xml(db_file.replace('.db', '.xml'))
        output_path = config['output']
        signing_path = signing_key_file
        key = open(signing_path, 'rb').read().rstrip(b'\n')
        output_file_path = output_path
        mac_file_path = f"{output_file_path}.mac"

        with open(output_file_path, 'w') as out_f, open(mac_file_path, 'w') as mac_f:
            query = None
            for element in ET.parse(db_file.replace('.db', '.xml')).getroot():
                if element.tag == 'query' and element.attrib.get('name') == query_name:
                    query = element.attrib['sql']
                    break

            if not query:
                print("query not found", file=sys.stderr)
                sys.exit(1)

            for param, value in params.items():
                query = query.replace(f"{{{{{param}}}}}", value)

            cursor.execute(query)
            rows = cursor.fetchall()

            for row in rows:
                line = '|'.join(str(val) if val is not None else '' for val in row)
                out_f.write(line + '\n')

                digest = hashlib.sha256(line.encode('utf-8')).digest()
                mac_line = keyed_digest(digest, key)
                mac_f.write(mac_line + '\n')

    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if 'conn' in locals():
            conn.close()

def keyed_digest(data, key):
    return hashlib.sha256(data + key).hexdigest().lower()

def main():
    if len(sys.argv) < 4:
        print("Usage: python report_runner.py CONFIG.xml QUERY_NAME PARAM=VALUE [PARAM=VALUE ...]", file=sys.stderr)
        sys.exit(1)

    xml_file = sys.argv[1]
    query_name = sys.argv[2]
    params = parse_params(sys.argv[3:])

    signing_key_file = None
    try:
        config = parse_xml(xml_file)
        signing_key_file = config['signing']
    except Exception:
        print("missing config element", file=sys.stderr)
        sys.exit(1)

    execute_query(config['database'], None, signing_key_file, query_name, params)

if __name__ == "__main__":
    main()
